// Validate & normalize incoming lead payload
const body = $input.first().json.body || $input.first().json;

const errors = [];
const name = (body.name || '').toString().trim();
const email = (body.email || '').toString().trim().toLowerCase();
const message = (body.message || body.notes || '').toString().trim();
const phone = (body.phone || '').toString().trim();
const company = (body.company || '').toString().trim();
const source = (body.source || 'website_form').toString().trim();
const budget = body.budget !== undefined ? Number(body.budget) : null;
const timeline = (body.timeline || '').toString().trim();
const requestId = (body.requestId || '').toString().trim();

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!name) errors.push('name is required');
if (!email) errors.push('email is required');
else if (!emailRegex.test(email)) errors.push('email format is invalid');
if (!message) errors.push('message is required');

// Idempotency key: prefer client-supplied requestId, else a hash of email+message
// (no time component, so a retried webhook delivery minutes later still produces
// the SAME key and gets caught by the duplicate check downstream, instead of
// silently creating a second lead). Uses a plain JS hash -- no 'crypto' require,
// so it runs in n8n's sandboxed Code node with no env config needed.
function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    hash = (Math.imul(31, hash) + str.charCodeAt(i)) | 0;
  }
  return (hash >>> 0).toString(16);
}

const idempotencySeed = requestId || `${email}|${message}`;
const idempotencyKey = simpleHash(idempotencySeed);

return [{
  json: {
    valid: errors.length === 0,
    errors,
    lead: {
      name, email, phone, company, source, budget, timeline, message,
      submittedAt: new Date().toISOString(),
      idempotencyKey
    }
  }
}];

// Determine duplicate-request status and lead submission throttling
const leadData = $('Validate & Normalize Lead').first().json.lead;
const existingRecords = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id); // drop the empty placeholder item Airtable returns on zero matches

const oneHourAgo = Date.now() - 60 * 60 * 1000;
const dedupWindowMs = 5 * 60 * 1000; // 5-minute duplicate window

// Duplicate request: same idempotency key seen within the last 5 minutes.
// (Matching on key alone is not enough -- a retried webhook delivery arriving
// minutes apart must still be caught, so we check the key AND a recency window.)
const isDuplicateRequest = existingRecords.some(r => {
  if (r.IdempotencyKey !== leadData.idempotencyKey) return false;
  const t = r.SubmittedAt ? new Date(r.SubmittedAt).getTime() : 0;
  return (Date.now() - t) <= dedupWindowMs;
});

// Lead submission throttling (business rule, not general API rate limiting):
// more than 5 submissions from this email in the last hour.
const submissionsLastHour = existingRecords.filter(r => {
  const t = r.SubmittedAt ? new Date(r.SubmittedAt).getTime() : 0;
  return t >= oneHourAgo;
}).length;
const isThrottled = submissionsLastHour >= 5;

const existingRecord = existingRecords.length > 0 ? existingRecords[0] : null;

return [{
  json: {
    lead: leadData,
    isDuplicateRequest,
    isThrottled,
    isReturningLead: !!existingRecord,
    existingRecordId: existingRecord ? existingRecord.id : null,
    blocked: isDuplicateRequest || isThrottled
  }
}];

