const raw = $json.choices[0].message.content;
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = {
    is_relevant: true,
    category: 'other',
    priority: 'medium',
    score: 50,
    summary: 'AI response could not be parsed; defaulted to medium priority for manual review.',
    reasoning: 'JSON parse failure on model output.'
  };
}
return [{ json: { ...parsed, aiSucceeded: true, aiFallbackUsed: false } }];

// Deterministic business rules layered on top of the AI/fallback output
const ai = $input.first().json;
const lead = $('Check Duplicate & Rate Limit').first().json.lead;
const existingRecordId = $('Check Duplicate & Rate Limit').first().json.existingRecordId;

let finalScore = ai.score;
let finalPriority = ai.priority;

// Rule: large declared budget always bumps to at least 'high'
if (lead.budget && lead.budget >= 20000) {
  finalPriority = 'high';
  finalScore = Math.max(finalScore, 85);
}

// Rule: enterprise/company-provided leads get a floor boost
if (lead.company && lead.company.length > 0 && finalPriority === 'low') {
  finalPriority = 'medium';
}

// Rule: known spam category is never marked high priority, regardless of AI
if (ai.category === 'spam') {
  finalPriority = 'low';
  ai.is_relevant = false;
}

return [{
  json: {
    lead,
    existingRecordId,
    isRelevant: ai.is_relevant,
    category: ai.category,
    priority: finalPriority,
    score: finalScore,
    summary: ai.summary,
    reasoning: ai.reasoning,
    aiSucceeded: ai.aiSucceeded,
    aiFallbackUsed: ai.aiFallbackUsed
  }
}];

// Rule-based fallback when the LLM call fails or times out
const lead = $('Check Duplicate & Rate Limit').first().json.lead;
const text = `${lead.message} ${lead.company}`.toLowerCase();
const spamKeywords = ['unsubscribe', 'seo services', 'crypto', 'casino'];
const isSpam = spamKeywords.some(k => text.includes(k));

const score = isSpam ? 5 : (lead.budget && lead.budget > 10000 ? 70 : 40);
const priority = isSpam ? 'low' : (lead.budget && lead.budget > 10000 ? 'high' : 'medium');

return [{
  json: {
    is_relevant: !isSpam,
    category: isSpam ? 'spam' : 'sales_inquiry',
    priority,
    score,
    summary: 'Categorized via rule-based fallback because the AI qualification call failed.',
    reasoning: 'LLM unavailable; used keyword and budget heuristics.',
    aiSucceeded: false,
    aiFallbackUsed: true
  }
}];

